-- Human-readable booking number shown to the customer, partner and master (for example KND-772431). Generated by the database.
CREATE SEQUENCE transactions.booking_number_seq START 100000 MINVALUE 100000;

ALTER TABLE transactions.bookings ADD COLUMN booking_number varchar(16) COLLATE "C";
UPDATE transactions.bookings SET booking_number = 'KND-' || nextval('transactions.booking_number_seq')::text;
ALTER TABLE transactions.bookings
    ALTER COLUMN booking_number SET DEFAULT ('KND-' || nextval('transactions.booking_number_seq')::text),
    ALTER COLUMN booking_number SET NOT NULL,
    ADD CONSTRAINT bookings_booking_number_key UNIQUE (booking_number),
    ADD CONSTRAINT bookings_booking_number_format CHECK (booking_number ~ '^KND-[0-9]{6,}$');

-- A Beauty promotion that applied when the booking was made: the customer pays price_minor, original_price_minor is the list price.
ALTER TABLE transactions.bookings
    ADD COLUMN original_price_minor bigint CHECK (original_price_minor IS NULL OR original_price_minor >= 0),
    ADD COLUMN discount_percent smallint CHECK (discount_percent IS NULL OR discount_percent BETWEEN 1 AND 90),
    ADD CONSTRAINT bookings_discount_consistent CHECK ((original_price_minor IS NULL) = (discount_percent IS NULL));
